@Component("payout-handler")
@ProcessingGroup("payout-processing-group")
public class PayoutEventHandler {
	
	// core constructor
	PayoutEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreatePayoutEvent
     */
    @EventHandler
    public void handle( CreatePayoutEvent event) {
        entityManager.persist(new Payout(event.getPayoutId(), event.getPayoutReference(), event.getAmount(), event.getCurrency(), event.getScheduledDate(), event.getPaidDate(), event.getMerchant(), event.getSettlementBatch(), event.getDestinationAccount(), event.getStatus()));
    }

    /*
     * @param	event UpdatePayoutEvent
     */
    @EventHandler
    public Payout handle( UpdatePayoutEvent event) {
    	entityManager.merge(new Payout(event.getPayoutId(), event.getPayoutReference(), event.getAmount(), event.getCurrency(), event.getScheduledDate(), event.getPaidDate(), event.getMerchant(), event.getSettlementBatch(), event.getDestinationAccount(), event.getStatus()));
    }
    
    /*
     * @param	event DeletePayoutEvent
     */
    @EventHandler
    public void on( DeletePayoutEvent event) {
    	Payout entity = new Payout();
   
    	// ------------------------------------------
    	// apply the PayoutId
    	// ------------------------------------------
    	entity.setPayoutId( event.getPayoutId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final PayoutRepository payoutEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(PayoutEventHandler.class.getName());

}
